import subprocess
import os
import random

def task_func(directory, file_list):
    if not file_list:
        return None

    candidates = []
    for name in file_list:
        path = name if os.path.isabs(name) else os.path.join(directory, name)
        if os.path.isfile(path):
            candidates.append(path)

    if not candidates:
        return None

    path = random.choice(candidates)

    try:
        if path.lower().endswith(".py"):
            proc = subprocess.Popen([os.sys.executable, path], cwd=directory)
        else:
            proc = subprocess.Popen([path], cwd=directory)
    except (OSError, ValueError):
        return None

    return proc.poll()
